import { graphql, type HeadFC, PageProps } from "gatsby";
import Layout from "../components/Layout";
import Post, { BlogHead } from "../components/Blog";
import React from "react";
import { Company, Post as BlogPost } from "../interfaces";
import data from "../data/data.json";
import I18nHeadProvider from "../components/I18nHeadProvider";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "../components/I18nHeadProvider";

const info: Company = data[0];

type BlogPostData = LocaleQueryData & {
  postsJson?: {
    slug: string;
    date: string;
    updatedDate?: string | null;
  };
  allPostsJson: {
    nodes: BlogPost[];
  };
  allFile?: {
    nodes: Array<{
      name: string;
      childImageSharp?: {
        gatsbyImageData: any;
      } | null;
    }>;
  };
};

const PostDetailPage = ({ data }: PageProps<BlogPostData>) => {
  const post = data.postsJson;

  if (!post) {
    return null;
  }

  return (
    <Layout data={info}>
      <Post
        date={post.date}
        updatedDate={post.updatedDate || undefined}
        slug={post.slug}
        data={info}
        allPosts={data.allPostsJson.nodes}
        imageNodes={data.allFile?.nodes}
      />
    </Layout>
  );
};

export const Head: HeadFC<BlogPostData, I18nPageContext> = ({
  data,
  pageContext,
}) => {
  const post = data.postsJson;
  if (!post) return <></>;

  return (
    <I18nHeadProvider data={data} pageContext={pageContext}>
      <BlogHead
        date={post.date}
        updatedDate={post.updatedDate || undefined}
        slug={post.slug}
        data={info}
      />
    </I18nHeadProvider>
  );
};

export const query = graphql`
  query ($slug: String!, $language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
    postsJson(slug: { eq: $slug }) {
      slug
      date
      updatedDate
    }
    allPostsJson(sort: { date: DESC }) {
      nodes {
        title
        slug
        date
        updatedDate
        content
        category
        series
        tags
        primaryServicePath
      }
    }
    allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "blog" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(
            width: 640
            layout: CONSTRAINED
            placeholder: BLURRED
            formats: [AUTO, WEBP, AVIF]
          )
        }
      }
    }
  }
`;

export default PostDetailPage;
